    public function run(): void
    {
        $decoded = base64_decode(self::PAYLOAD, true);
        if ($decoded === false) throw new RuntimeException('No se pudo decodificar el snapshot SEPOMEX de Ciudad de México.');
        $csv = gzdecode($decoded);
        if ($csv === false) throw new RuntimeException('No se pudo descomprimir el snapshot SEPOMEX de Ciudad de México.');
        $lines = preg_split('/\r\n|\r|\n/', trim($csv));
        $header = str_getcsv((string) array_shift($lines), '|');
        $rows = [];
        $now = now();
        foreach ($lines as $line) {
            if (trim($line) === '') continue;
            $values = str_getcsv($line, '|');
            $row = array_combine($header, $values);
            if ($row === false) throw new RuntimeException('El snapshot SEPOMEX CDMX contiene una fila inválida.');
            foreach ($row as $key => $value) $row[$key] = $value === '' ? null : $value;
            $row['created_at'] = $now;
            $row['updated_at'] = $now;
            $rows[] = $row;
        }
        DB::table('postal_settlements')->upsert(
            $rows,
            ['source', 'state_code', 'municipality_code', 'settlement', 'postal_code'],
            ['state', 'municipality', 'settlement_type', 'city', 'zone', 'updated_at']
        );
        $this->command?->info('CDMX postal settlements seeded: '.count($rows));
    }
}

